-- ==============================================================================
-- 104_Create_PAYMENT_METHOD_Table.sql
-- Create PAYMENT_METHOD table and seed default methods for ThinkOn ERP Accounting
-- ==============================================================================

CREATE TABLE "PAYMENT_METHOD" (
    "ID" NUMBER(19) GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    "BRANCH_ID" NUMBER(19) NOT NULL,
    "CODE" NVARCHAR2(50) NOT NULL,
    "NAME_LOCAL" NVARCHAR2(200) NOT NULL,
    "NAME_EN" NVARCHAR2(200) NOT NULL,
    "METHOD_TYPE" NVARCHAR2(30) NOT NULL,
    "GL_ACCOUNT_CODE" NVARCHAR2(50) NOT NULL,
    "BANK_ACCOUNT_ID" NUMBER(19) NULL,
    "CASH_REGISTER_ID" NUMBER(19) NULL,
    "COMMISSION_PERCENT" NUMBER(8, 4) DEFAULT 0 NOT NULL,
    "COMMISSION_FIXED_AMOUNT" NUMBER(18, 4) DEFAULT 0 NOT NULL,
    "COMMISSION_GL_ACCOUNT_CODE" NVARCHAR2(50) NULL,
    "REQUIRES_REFERENCE" NUMBER(1) DEFAULT 0 NOT NULL,
    "REQUIRES_DUE_DATE" NUMBER(1) DEFAULT 0 NOT NULL,
    "AUTO_POST_GL" NUMBER(1) DEFAULT 1 NOT NULL,
    "SHOW_IN_POS" NUMBER(1) DEFAULT 1 NOT NULL,
    "SHOW_IN_INVOICES" NUMBER(1) DEFAULT 1 NOT NULL,
    "SHOW_IN_VOUCHERS" NUMBER(1) DEFAULT 1 NOT NULL,
    "IS_ACTIVE" NUMBER(1) DEFAULT 1 NOT NULL,
    "DISPLAY_ORDER" NUMBER(5) DEFAULT 1 NOT NULL,
    "CREATION_USER" NVARCHAR2(50) NOT NULL,
    "CREATION_DATE" TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    "UPDATE_USER" NVARCHAR2(50) NULL,
    "UPDATE_DATE" TIMESTAMP NULL,
    CONSTRAINT "UX_PAYMENT_METHOD_BRANCH_CODE" UNIQUE ("BRANCH_ID", "CODE")
);

-- Foreign Keys
ALTER TABLE "PAYMENT_METHOD" ADD CONSTRAINT "FK_PM_BRANCH" FOREIGN KEY ("BRANCH_ID") REFERENCES "SYS_BRANCH"("ID");
ALTER TABLE "PAYMENT_METHOD" ADD CONSTRAINT "FK_PM_GL_ACCOUNT" FOREIGN KEY ("GL_ACCOUNT_CODE") REFERENCES "GL_ACCOUNT"("ACCOUNT_CODE");
ALTER TABLE "PAYMENT_METHOD" ADD CONSTRAINT "FK_PM_COMM_GL_ACCOUNT" FOREIGN KEY ("COMMISSION_GL_ACCOUNT_CODE") REFERENCES "GL_ACCOUNT"("ACCOUNT_CODE");
ALTER TABLE "PAYMENT_METHOD" ADD CONSTRAINT "FK_PM_BANK_ACCOUNT" FOREIGN KEY ("BANK_ACCOUNT_ID") REFERENCES "BANK_ACCOUNT"("ID");
ALTER TABLE "PAYMENT_METHOD" ADD CONSTRAINT "FK_PM_CASH_REGISTER" FOREIGN KEY ("CASH_REGISTER_ID") REFERENCES "CASH_REGISTER"("ID");

-- Seed Default Payment Methods for Branch 1
MERGE INTO "PAYMENT_METHOD" t
USING (SELECT 1 AS b, 'CASH' AS c FROM dual) s
ON (t."BRANCH_ID" = s.b AND t."CODE" = s.c)
WHEN NOT MATCHED THEN
    INSERT ("BRANCH_ID", "CODE", "NAME_LOCAL", "NAME_EN", "METHOD_TYPE", "GL_ACCOUNT_CODE",
            "COMMISSION_PERCENT", "COMMISSION_FIXED_AMOUNT", "COMMISSION_GL_ACCOUNT_CODE",
            "REQUIRES_REFERENCE", "REQUIRES_DUE_DATE", "AUTO_POST_GL",
            "SHOW_IN_POS", "SHOW_IN_INVOICES", "SHOW_IN_VOUCHERS",
            "IS_ACTIVE", "DISPLAY_ORDER", "CREATION_USER", "CREATION_DATE")
    VALUES (1, 'CASH', N'نقدي - الصندوق الرئيسي', 'Cash - Main Register', 'CASH', '111101', 0, 0, NULL, 0, 0, 1, 1, 1, 1, 1, 1, 'SYSTEM', SYSTIMESTAMP);

